import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"代工路线对比","description":"","frontmatter":{"title":"代工路线对比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/foundry-roadmap-compare.md","filePath":"litho/foundry-roadmap-compare.md","lastUpdated":1789023840000}'),E={name:"litho/foundry-roadmap-compare.md"};function m(A,a,c,_,u,f){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="代工路线对比" tabindex="-1">代工路线对比 <a class="header-anchor" href="#代工路线对比" aria-label="Permalink to &quot;代工路线对比&quot;">​</a></h1><div class="epigraph"><p>同一世代名下，EUV 层数、高 NA 时间表、GAA/CFET 与背面电源可以完全不同；对比要按层策略，不按广告同步。</p><footer>—— 对照领先代工公开节点路径的结构差异；不编造未公布层数</footer></div><p><a href="/litho/pfas-resist-regulation">上一课</a>把材料风险放进规划。缺口是各厂怎么走。本课钉代工路线对比。存储器路径不同，留给[下一课](/litho/memory-litho-dram-nand）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TSMC、Intel、Samsung 等公开叙事在：EUV 插入早晚、是否 High-NA、FinFET 到 GAA 的时间、背面电源、命名（N3/N2 vs 18A）。光刻含义：EUV 层数改交叉与瓶颈；High-NA 改半场与薄胶；GAA 改切线与片间距图形。对比必须引用当时公开材料并注明年份，不能把传闻层表当课文本体。</p><p>缺口是<strong>路径分叉</strong>，不是谁赢。把三家画成同一条 IRDS 线，会误导 DTCO。</p><h3 id="公开可说的" tabindex="-1">公开可说的 <a class="header-anchor" href="#公开可说的" aria-label="Permalink to &quot;公开可说的&quot;">​</a></h3><p>结构差异类型：先全 DUV 多重再插 EUV vs 较早 EUV；High-NA 作为研究 vs 插入计划；混跑策略。具体层清单以各厂公开为准，本课不发明。</p><p><span class="marginnote">客户选择代工等于选择一套光刻约束（设计规则、EUV 随机、拼接）。IP 可移植性有光刻成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列比较轴：CPP/MMP（若公开）、EUV 使用、High-NA、器件架构、封装/键合。每轴用公开出处。内部决策仍用自己的交叉模型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>各厂资本存量（已有浸没台数、EUV 台数）、客户组合、风险偏好，使同一物理极限下的插入顺序不同。这是经济与组织，不是光学常数不同。</p>',13)),(e(),s(p,null,{default:o(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E6%9E%81%E9%99%90%22%5D%20--%3E%20PATH%5B%22%E6%8F%92%E5%85%A5%E9%A1%BA%E5%BA%8F%E5%88%86%E5%8F%89%22%5D%0A%20%20CAP%5B%22%E5%B7%B2%E6%9C%89%E6%9C%BA%E5%8F%B0%E5%AD%98%E9%87%8F%22%5D%20--%3E%20PATH%0A%20%20PATH%20--%3E%20DR%5B%22%E4%B8%8D%E5%90%8C%20PDK%20%2F%20%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不排名。不泄露非公开层数。路线会改，课文钉轴而不是钉某年新闻。</p><p>后课默认：逻辑代工路径分叉；下一课 DRAM/NAND 的光刻负担与逻辑不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代工对比按 EUV 层策略、High-NA、器件架构等轴，不按商品名同步。</li><li>只引用公开材料并注明年份。</li><li>分叉来自资本存量与风险，不来自另一套光学。</li><li>出处：领先代工公开节点叙事的结构对照。</li></ul>',5))])}const D=i(E,[["render",m]]);export{T as __pageData,D as default};
